fn xmlRegStateAddTransTo(
    mut ctxt: xmlRegParserCtxtPtr,
    mut target: xmlRegStatePtr,
    mut from: c_int,
) { unsafe {
    let state = &mut *target;

    let nb = state.nbTransTo;
    let max = state.maxTransTo;

    if max == 0 as c_int {
        let new_max = 8 as c_int;
        let trans_to = xmlMalloc.expect("non-null function pointer")(
            (new_max as size_t).wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
        ) as *mut c_int;
        if trans_to.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            state.maxTransTo = 0 as c_int;
            return;
        }
        state.maxTransTo = new_max;
        state.transTo = trans_to;
    } else if nb >= max {
        let new_max = max * 2 as c_int;
        let tmp = xmlRealloc.expect("non-null function pointer")(
            state.transTo as *mut c_void,
            (new_max as size_t).wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
        ) as *mut c_int;
        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            state.maxTransTo = max;
            return;
        }
        state.maxTransTo = new_max;
        state.transTo = tmp;
    }

    // SAFETY: transTo has been allocated/reallocated to hold at least nbTransTo + 1 elements above, and nb is the current in-bounds write index.
    *state.transTo.add(nb as usize) = from;
    state.nbTransTo = nb + 1;
} }

